        "палица"                                  : { type: "оружие",               cost: "2 см", rank: 0, weight: "10 фнт", usage: "", material: "Железо", tools: "Кузнеца", desc: "Тяжелое двуручное оружие с массивной головкой из металла или дерева. Головка может быть украшена шипами или ребрами, что усиливает разрушающий эффект при ударе.", value: 5 },
        "коса"                                    : { type: "оружие",               cost: "3 см", rank: 0, weight: "2 фнт", usage: "", material: "Железо", tools: "Кузнеца", desc: "Длинное изогнутое лезвие, прикрепленное к длинной деревянной рукояти. Обычно используется в сельском хозяйстве, но в бою коса наносит широкие, рубящие удары, способные разрезать нескольких противников сразу.", value: 10 },
