        'Лиадрин Звёздный Шёлк', 'Наэрон Певчий Ручей', 'Аэлира Сапфировый Взор', 'Файран Тонкая Тень', 'Саэлис Янтарный Лист',
        'Кайлен Лунный Резец', 'Мирэлия Ветвь Солнца', 'Эйрин Ночной Нектар', 'Талион Речной Камень', 'Сианна Нежный Мох',
        'Лоринэль Светлый Снег', 'Ариэнн Шелест Листьев', 'Валарион Пыльца Зари', 'Нимриэль Звон Кристалла', 'Рианор Тихий Огонь'
