    function toolToProfession(tool) {
        const t = String(tool || '').trim()

        const map = {
            'Воровские': 'Вор',
            'Алхимические': 'Алхимик',
            'Кузнеца': 'Кузнец',
            'Каллиграфа': 'Каллиграф',
            'Поддельщика': 'Поддельщик',
            'Гримёра': 'Гримёр',
            'Художественные': 'Художник',
            'Исследователя': 'Исследователь',
            'Жестянщика': 'Жестянщик',
            'Камнелома': 'Камнелом',
            'Кожедела': 'Кожедел',
            'Пивовара': 'Пивовар',
            'Деревянщика': 'Деревянщик',
            'Повара': 'Повар',
            'Ювелира': 'Ювелир'
        }

        return map[t] || t
    }

